-- The maps of Xfinity Mobile Arena, Citizens Bank Park and Subaru Park (Sean, 2026-10-29: the seating charts he sent as screenshots),
-- read the same way as the others: each level's sections clockwise by side. We draw our own map; only the numbers come from the charts.
-- Xfinity Mobile Arena is drawn as a court (the 76ers and the Flyers share one chart); its loge boxes (1 to 82, A to R) are left off.
-- Citizens Bank Park is drawn with home plate at the bottom; its lettered sections B to F behind home are on the 100 level.

update public.ve_venues set layout = '{"field": "basketball", "ring_m": 500, "levels": [{"level": "100", "name": "100 level", "sides": {"top": ["115", "114", "113", "112", "111"], "tr": ["110", "109"], "right": ["108", "107", "106"], "br": ["105", "104"], "bottom": ["103", "102", "101", "124", "123"], "bl": ["122", "121"], "left": ["120", "119", "118"], "tl": ["117", "116"]}}, {"level": "C", "name": "Club level (C sections)", "sides": {"top": ["C15", "C14", "C13", "C12", "C11"], "tr": ["C10"], "br": ["C4"], "bottom": ["C3", "C2", "C1", "C24", "C23"], "bl": ["C22"], "tl": ["C16", "C17"]}}, {"level": "200", "name": "200 level", "sides": {"top": ["215", "214", "213", "212", "211"], "tr": ["210A", "210", "209A"], "right": ["209", "208", "207A", "207", "206"], "br": ["205A", "205", "204A", "204"], "bottom": ["203", "202", "201", "224", "223"], "bl": ["222A", "222", "221A", "221"], "left": ["220", "219A", "219", "218"], "tl": ["217A", "217", "216A", "216"]}}]}'::jsonb where slug = 'xfinity-mobile-arena';
update public.ve_venues set layout = '{"field": "baseball", "ring_m": 900, "levels": [{"level": "100", "name": "100 level (and the lettered sections behind home)", "sides": {"top": ["147"], "right": ["102", "104", "108", "109", "111", "113", "115"], "bottom": ["122", "F", "E", "D", "C", "B", "125"], "left": ["133", "136", "138", "139", "140"], "tl": ["141"]}}, {"level": "200", "name": "200 level", "sides": {"right": ["202", "203", "206", "207", "208", "209", "210"], "br": ["219"], "bottom": ["221", "224", "225"], "bl": ["229", "230"], "left": ["233", "234", "235", "236", "237"], "tl": ["241"]}}, {"level": "300", "name": "300 level", "sides": {"right": ["301", "303", "304", "305", "306", "307", "308", "309", "310"], "br": ["314", "317", "319"], "bottom": ["320", "321", "322"], "bl": ["324"], "left": ["330", "331", "332", "333"]}}, {"level": "400", "name": "400 level", "sides": {"right": ["413", "414", "415", "416", "417"], "br": ["418"], "bottom": ["419", "420", "421", "422"], "bl": ["423", "424", "425", "426", "427", "428"], "left": ["430", "431", "432", "433"]}}]}'::jsonb where slug = 'citizens-bank-park';
update public.ve_venues set layout = '{"field": "soccer", "ring_m": 650, "levels": [{"level": "100", "name": "100 level", "sides": {"tl": ["140", "101"], "top": ["103", "104", "105", "106", "107", "108", "109", "110", "111"], "tr": ["112"], "right": ["115", "116", "117", "118", "119"], "br": ["120"], "bottom": ["122", "123", "124", "125", "126", "127", "128", "129", "130", "131"], "bl": ["132"], "left": ["134", "135", "136", "137", "138", "139"]}}, {"level": "300", "name": "300 level", "sides": {"bottom": ["320", "322", "325", "328", "330", "333", "335", "337", "339"]}}]}'::jsonb where slug = 'subaru-park';
